///  Root FlatBuffers type for every fallible FFI call that returns composite data.
///
///  ok == true  → data is set to the concrete Payload variant; error is absent.
///  ok == false → error is set (code + context); data is absent (Payload::NONE).
///
///  Dart reads the buffer via the generated typed accessors. It is released by
///  reclaiming the exact Rust allocation through one of two equivalent paths:
///  zanshin_buffer_free(ptr, len) for synchronous call sites, or the
///  NativeFinalizer-backed token path (zanshin_buffer_free_token) used by the
///  FfiBuffer wrapper as a belt-and-suspenders backstop
///  (see app/lib/src/ffi/ffi_buffer.dart).
class Envelope {
  Envelope._(this._bc, this._bcOffset);
  factory Envelope(List<int> bytes) {
    final rootRef = fb.BufferContext.fromBytes(bytes);
    return reader.read(rootRef, 0);
  }

  static const fb.Reader<Envelope> reader = _EnvelopeReader();

  final fb.BufferContext _bc;
  final int _bcOffset;

  bool get ok => const fb.BoolReader().vTableGet(_bc, _bcOffset, 4, false);
  FfiError? get error => FfiError.reader.vTableGetNullable(_bc, _bcOffset, 6);
  PayloadTypeId? get dataType =>
      PayloadTypeId._createOrNull(const fb.Uint8Reader().vTableGetNullable(_bc, _bcOffset, 8));
  dynamic get data {
    switch (dataType?.value) {
      case 1:
        return RepoHandle.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 2:
        return Diagnostics.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 3:
        return Status.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 4:
        return Change.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 5:
        return OpLog.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 6:
        return Bookmarks.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 7:
        return Remotes.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 8:
        return RepoDetect.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 9:
        return WatcherEvent.reader.vTableGetNullable(_bc, _bcOffset, 10);
      case 10:
        return Progress.reader.vTableGetNullable(_bc, _bcOffset, 10);
      default:
        return null;
    }
  }

  @override
  String toString() {
    return 'Envelope{ok: ${ok}, error: ${error}, dataType: ${dataType}, data: ${data}}';
  }
}

class _EnvelopeReader extends fb.TableReader<Envelope> {
  const _EnvelopeReader();

  @override
  Envelope createObject(fb.BufferContext bc, int offset) => Envelope._(bc, offset);
}

class EnvelopeBuilder {
  EnvelopeBuilder(this.fbBuilder);

  final fb.Builder fbBuilder;

  void begin() {
    fbBuilder.startTable(4);
  }

  int addOk(bool? ok) {
    fbBuilder.addBool(0, ok);
    return fbBuilder.offset;
  }

  int addErrorOffset(int? offset) {
    fbBuilder.addOffset(1, offset);
    return fbBuilder.offset;
  }

  int addDataType(PayloadTypeId? dataType) {
    fbBuilder.addUint8(2, dataType?.value);
    return fbBuilder.offset;
  }

  int addDataOffset(int? offset) {
    fbBuilder.addOffset(3, offset);
    return fbBuilder.offset;
  }

  int finish() {
    return fbBuilder.endTable();
  }
}

class EnvelopeObjectBuilder extends fb.ObjectBuilder {
  final bool? _ok;
  final FfiErrorObjectBuilder? _error;
  final PayloadTypeId? _dataType;
  final dynamic _data;

  EnvelopeObjectBuilder({
    bool? ok,
    FfiErrorObjectBuilder? error,
    PayloadTypeId? dataType,
    dynamic data,
  }) : _ok = ok,
       _error = error,
       _dataType = dataType,
       _data = data;

  /// Finish building, and store into the [fbBuilder].
  @override
  int finish(fb.Builder fbBuilder) {
    final int? errorOffset = _error?.getOrCreateOffset(fbBuilder);
    final int? dataOffset = _data?.getOrCreateOffset(fbBuilder);
    fbBuilder.startTable(4);
    fbBuilder.addBool(0, _ok);
    fbBuilder.addOffset(1, errorOffset);
    fbBuilder.addUint8(2, _dataType?.value);
    fbBuilder.addOffset(3, dataOffset);
    return fbBuilder.endTable();
  }

  /// Convenience method to serialize to byte list.
  @override
  Uint8List toBytes([String? fileIdentifier]) {
    final fbBuilder = fb.Builder(deduplicateTables: false);
    fbBuilder.finish(finish(fbBuilder), fileIdentifier);
    return fbBuilder.buffer;
  }
}
